import{_ as n}from"./chunks/ArticleMetadata.1_--bNMz.js";import{_ as a,D as c,o as r,c as g,I as p,w as h,k as l,a as d,R as S,b as k,e as u}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const A=JSON.parse('{"title":"MCP、Tools、Skills 与集成","description":"","frontmatter":{"title":"MCP、Tools、Skills 与集成","author":"阿源","date":"2026/10/07 00:00","categories":["Agent 开发"],"tags":["MCP","Tools","Skills","Plugin"],"status":"预览版导航"},"headers":[],"relativePath":"courses/agent/01-项目与知识库导航/04-MCP工具Skills与集成.md","filePath":"courses/agent/01-项目与知识库导航/04-MCP工具Skills与集成.md","lastUpdated":1791349179000}'),m={name:"courses/agent/01-项目与知识库导航/04-MCP工具Skills与集成.md"},f=l("h1",{id:"mcp、tools、skills-与集成",tabindex:"-1"},[d("MCP、Tools、Skills 与集成 "),l("a",{class:"header-anchor",href:"#mcp、tools、skills-与集成","aria-label":'Permalink to "MCP、Tools、Skills 与集成"'},"​")],-1),P=S('<p>这一页刻意把四个容易混淆的词拆开：Tool 是一次可调用能力，MCP 是连接应用与外部能力的协议，Skill 是完成一类任务的方法和上下文，Plugin 是宿主可装配的扩展单元。先读 <a href="/courses/agent/04-Tool-Calling与Agent-Loop/01-函数调用与JSON-Schema">04 Tool Calling</a>，再按协议、实现和工作方法进入以下资源。</p><p>本页以 <strong>MCP 2026-07-28 规范</strong>为协议基线；实现优先看官方 TypeScript SDK v2 与当前官方 Python SDK。旧 v1 教程、包名和初始化/会话假设只作为迁移对照，不作为新示例的默认写法。</p><h2 id="mcp-typescript-sdk" tabindex="-1">MCP TypeScript SDK <a class="header-anchor" href="#mcp-typescript-sdk" aria-label="Permalink to &quot;MCP TypeScript SDK&quot;">​</a></h2><p>官方入口：<a href="https://github.com/modelcontextprotocol/typescript-sdk" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://ts.sdk.modelcontextprotocol.io/v2/" target="_blank" rel="noreferrer">官方 TypeScript SDK v2 文档</a> · <a href="https://ts.sdk.modelcontextprotocol.io/v2/migration/support-2026-07-28" target="_blank" rel="noreferrer">2026-07-28 适配说明</a></p><ul><li><strong>解决的问题</strong>：用官方 SDK 实现 MCP Client/Server、tools/resources/prompts、传输和授权。</li><li><strong>推荐学习内容</strong>：先阅读 v2 Server tutorial，再按 Client、transport、capability、错误和 2026-07-28 适配说明查阅；旧 <code>@modelcontextprotocol/sdk</code> v1 包结构只用于迁移对照。</li><li><strong>前置知识</strong>：MCP 的 Host/Client/Server 模型；只需能读懂当前 TypeScript 类型和异步调用。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：主线精读。</li><li><strong>推荐目录/文章</strong>：v2 十分钟 Server tutorial、2026-07-28 适配说明、<code>packages/server</code>、<code>packages/client</code>、<code>examples</code>。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：MCP capability、transport 和 tool result 对应 dsh 的能力插件与外部工具边界；协议连接不等于内部插件生命周期。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="mcp-python-sdk" tabindex="-1">MCP Python SDK <a class="header-anchor" href="#mcp-python-sdk" aria-label="Permalink to &quot;MCP Python SDK&quot;">​</a></h2><p>官方入口：<a href="https://github.com/modelcontextprotocol/python-sdk" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://py.sdk.modelcontextprotocol.io/" target="_blank" rel="noreferrer">官方文档</a> · <a href="https://py.sdk.modelcontextprotocol.io/migration/" target="_blank" rel="noreferrer">迁移指南</a></p><ul><li><strong>解决的问题</strong>：用当前官方 Python SDK 构建 MCP Server/Client，并覆盖 tools、resources、prompts 与标准 transport。</li><li><strong>推荐学习内容</strong>：按当前官方文档的 Get started → Servers → Clients → Protocol versions 阅读，案例默认使用当前 <code>mcp</code> 包和 Python 3.10+；旧 v1 教程的导入路径、FastMCP/Server 结构和 session/initialize 假设需逐项对照迁移指南。</li><li><strong>前置知识</strong>：第 02–06 章的 Agent Loop、Tool、JSON-RPC、transport 和授权边界；Python 异步基础。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：运行实验。</li><li><strong>推荐目录/文章</strong>：Installation、First steps、Testing、Servers/Tools、Clients、Protocol versions、Migration Guide。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：Python SDK 的 Server/Client 与 transport 对应 dsh 外部能力插件边界；SDK 不替代 dsh 的审批、沙箱和事件审计。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="mcp-specification-2026-07-28" tabindex="-1">MCP Specification（2026-07-28） <a class="header-anchor" href="#mcp-specification-2026-07-28" aria-label="Permalink to &quot;MCP Specification（2026-07-28）&quot;">​</a></h2><p>官方入口：<a href="https://modelcontextprotocol.io/specification/2026-07-28" target="_blank" rel="noreferrer">Model Context Protocol Specification 2026-07-28</a> · <a href="https://github.com/modelcontextprotocol/modelcontextprotocol" target="_blank" rel="noreferrer">规范仓库</a></p><ul><li><strong>解决的问题</strong>：定义跨 Host、Client、Server 的消息、能力、资源、工具、提示、传输和生命周期契约。</li><li><strong>推荐学习内容</strong>：按 Architecture → Base Protocol → Server/Client Features → Extensions → Security 阅读；以 2026-07-28 规范为准，旧版本只用于迁移对照。</li><li><strong>前置知识</strong>：JSON-RPC 基本概念；第 06 章。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：主线精读。</li><li><strong>推荐目录/文章</strong>：Architecture、Base Protocol、Server Features、Client Features、Extensions、Security。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：MCP 能力协商与授权是 dsh 接入外部工具时的协议边界，不替代 dsh 内部插件注册与事件生命周期。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="mcp-官方服务器集合" tabindex="-1">MCP 官方服务器集合 <a class="header-anchor" href="#mcp-官方服务器集合" aria-label="Permalink to &quot;MCP 官方服务器集合&quot;">​</a></h2><p>官方入口：<a href="https://github.com/modelcontextprotocol/servers" target="_blank" rel="noreferrer">GitHub</a></p><ul><li><strong>解决的问题</strong>：提供可运行的 MCP Server 实例，用于观察 tool schema、资源暴露、错误和权限。</li><li><strong>推荐学习内容</strong>：选择一个无敏感数据的本地 server 运行，检查 README、schema、权限与日志；不要默认启用有写权限的服务。</li><li><strong>前置知识</strong>：MCP Host/Client/Server；本地进程和权限基础。</li><li><strong>学习阶段</strong>：入门。</li><li><strong>阅读深度</strong>：运行实验。</li><li><strong>推荐目录/文章</strong>：README、filesystem server、每个 server 的安全说明、测试用例。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：可把 server 视作 dsh 的外部工具插件，比较进程边界、schema、授权和审计责任。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="agent-skills-specification" tabindex="-1">Agent Skills Specification <a class="header-anchor" href="#agent-skills-specification" aria-label="Permalink to &quot;Agent Skills Specification&quot;">​</a></h2><p>官方入口：<a href="https://agentskills.io/specification" target="_blank" rel="noreferrer">Specification</a> · <a href="https://agentskills.io/" target="_blank" rel="noreferrer">首页</a></p><ul><li><strong>解决的问题</strong>：约定如何以渐进式上下文包装可复用任务能力、脚本、资源和验证步骤。</li><li><strong>推荐学习内容</strong>：先读 frontmatter、目录布局、渐进加载和脚本边界，再对比 Skill、Tool、MCP、Plugin 的职责。</li><li><strong>前置知识</strong>：Markdown frontmatter；第 07 章。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：专题查阅。</li><li><strong>推荐目录/文章</strong>：Specification、What are skills?、Writing skills、Security considerations。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：Skill 的渐进式上下文与验证步骤对应 dsh Skill 插件，加载和生命周期仍以 dsh 源码为准。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="一次集成的检查顺序" tabindex="-1">一次集成的检查顺序 <a class="header-anchor" href="#一次集成的检查顺序" aria-label="Permalink to &quot;一次集成的检查顺序&quot;">​</a></h2><ol><li>先写 Tool schema 和本地确定性实现，确认输入、输出、错误与幂等边界。</li><li>再用 MCP 暴露能力，明确 Host/Client/Server 及 transport；敏感 HTTP 能力另做授权和 token audience 校验。</li><li>用 Skill 写任务方法和渐进式上下文，不把密钥、账号、偶然环境状态写进 Skill。</li><li>宿主需要热插拔、生命周期和事件拦截时，再引入 Plugin/Hook；把工具结果当不可信数据处理。</li></ol>',19);function C(t,_,M,b,v,y){const s=n,i=c("ClientOnly");return r(),g("div",null,[f,p(i,null,{default:h(()=>{var e,o;return[(((e=t.$frontmatter)==null?void 0:e.aside)??!0)&&(((o=t.$frontmatter)==null?void 0:o.showArticleMetadata)??!0)?(r(),k(s,{key:0,article:t.$frontmatter},null,8,["article"])):u("",!0)]}),_:1}),P])}const H=a(m,[["render",C]]);export{A as __pageData,H as default};
